const ACCOUNT_ID = 'a706de72-ef6f-11ed-ae54-78ac440eef32';
const PAGES = 3; // 3 x 35 = bis zu 105 Produkte; bei mehr hochsetzen

// inventory ist synchron (kein warm-up), max 35 Zeilen/Seite -> ein Item pro Seite
return Array.from({ length: PAGES }, (_, i) => ({ json: {
  tool: 'inventory',
  arguments: {
    account_id: ACCOUNT_ID,
    page: i + 1,
    count: 35,
    show_out_of_stock: true,
    sort: 'RunningOutOfStock',
    sort_direction: 'desc'
  }
}}));

const items = $input.all().map(i => i.json);
const fehler = items.filter(i => !i.ok).map(i => i.error);
if (fehler.length === items.length) throw new Error('Alle inventory-Calls fehlgeschlagen: ' + fehler.join(' | '));

const okItems = items.filter(i => i.ok);
const details = okItems[0]?.payload?.details || {};
const total = okItems[0]?.payload?.total ?? 0;
const rows = okItems.flatMap(i => i.payload?.result || []);

// Reorder-Kandidaten: Flags kommen als Strings ("NO"/"YES"), nicht als Boolean.
// DaysOfStockLeft = 0 heisst bei SalesVelocity = 0 nur "keine Velocity", NICHT out of stock -> deshalb Flags nutzen.
const kandidaten = rows
  .filter(r => r.TimeToReorder !== 'NO' || r.RunningOutOfStock !== 'NO' || (r.QtyToReorder || 0) > 0)
  .map(r => ({
    asin: r.ASIN,
    sku: r.SKU,
    name: String(r.Name || '').slice(0, 60),
    kanal: r.Channel,
    fba_bestand: r.FBAStock,
    unterwegs: r.SentToFBA,
    bestellt: r.Ordered,
    velocity_pro_tag: r.SalesVelocity,
    tage_reichweite: r.DaysOfStockLeft,
    tage_bis_reorder: r.DaysToReorder,
    menge_reorder: r.QtyToReorder,
    ek_stueck: r.Cost,
    investition: Math.round((r.QtyToReorder || 0) * (r.Cost || 0) * 100) / 100,
    laeuft_leer: r.RunningOutOfStock,
    reorder_faellig: r.TimeToReorder,
    lost_sales: r.LostSales,
    link: r.LinkToAmazon,
    product_id: r.ProductID
  }))
  .sort((a, b) => (a.tage_bis_reorder ?? 999) - (b.tage_bis_reorder ?? 999));

const ar = details.actionRequired || {};
const fmt = n => (n ?? 0).toLocaleString('de-DE', { minimumFractionDigits: 0, maximumFractionDigits: 0 });

const zeilen = kandidaten.slice(0, 15).map(k =>
  `• <${k.link}|${k.asin}> ${k.name} — FBA ${k.fba_bestand} (+${k.unterwegs} unterwegs, +${k.bestellt} bestellt), ${k.velocity_pro_tag}/Tag, Reorder in ${k.tage_bis_reorder === 999 ? '–' : k.tage_bis_reorder + ' Tagen'}, Menge ${k.menge_reorder} ≈ ${fmt(k.investition)} EUR`
);

const message = [
  `*Sellerboard Restock-Check* · ${total} Produkte · Lagerwert ${fmt(details.total?.costOfGoods)} EUR (EK)`,
  `Handlungsbedarf: *${ar.productsCount ?? 0} Produkte* · Investition ${fmt(ar.investmentNeeded)} EUR · Umsatz in Gefahr ${fmt(ar.salesAtRisk)} EUR · Gewinn in Gefahr ${fmt(ar.profitAtRisk)} EUR`,
  ...zeilen,
  kandidaten.length > 15 ? `… und ${kandidaten.length - 15} weitere` : '',
  fehler.length ? `:warning: ${fehler.length} Seite(n) nicht geladen` : ''
].filter(Boolean).join('\n');

return [{ json: { anzahl: kandidaten.length, action_required: ar, kandidaten, message } }];
